const range = [16, 225] as const;
const margin = { top: 10, right: 0, bottom: 0, left: 0 };

const renderTooltip = (props: TooltipContentProps<string | number, string>) => {
  const { active, payload } = props;

  if (active && payload && payload.length) {
    const data = payload[0] && payload[0].payload;

    return (
      <div
        style={{
          backgroundColor: '#fff',
          border: '1px solid #999',
          margin: 0,
          padding: 10,
        }}
      >
        <p>{data.hour}</p>
        <p>
          <span>value: </span>
          {data.value}
        </p>
      </div>
    );
  }

  return null;
};

const BubbleAxes = ({ day, showXTicks = false }: { day: string; showXTicks?: boolean }) => (
  <>
    <XAxis
      type="category"
      dataKey="hour"
      name="hour"
      interval={0}
      tick={showXTicks || { fontSize: 0 }}
      tickLine={{ transform: 'translate(0, -6)' }}
    />
    <YAxis
      type="number"
      dataKey="index"
      name="sunday"
      height={10}
      width={80}
      tick={false}
      tickLine={false}
      axisLine={false}
      label={{ value: day, position: 'insideRight' }}
    />
    <ZAxis type="number" dataKey="value" domain={domain} range={range} />
  </>
);

const MyTooltip = () => (
  <Tooltip cursor={{ strokeDasharray: '3 3' }} wrapperStyle={{ zIndex: 100 }} content={renderTooltip} />
);

const Bubbles = ({ data }: { data: Array<unknown> }) => <Scatter data={data} fill="#8884d8" />;

const DayChart = ({ children }: { children: ReactNode }) => (
  <ScatterChart
    margin={margin}
    style={{ width: '100%', minWidth: '700px', maxWidth: '900px', height: '60px' }}
    responsive
  >
    {children}
  </ScatterChart>
);

const BubbleChart = () => {
  return (
    <div style={{ width: '100%', maxWidth: '900px' }}>
      <DayChart>
        <BubbleAxes day="Sunday" />
        <Bubbles data={data01} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Monday" />
        <Bubbles data={data02} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Tuesday" />
        <Bubbles data={data01} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Wednesday" />
        <Bubbles data={data02} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Thursday" />
        <Bubbles data={data01} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Friday" />
        <Bubbles data={data02} />
        <MyTooltip />
      </DayChart>

      <DayChart>
        <BubbleAxes day="Saturday" showXTicks />
        <Bubbles data={data01} />
        <MyTooltip />
      </DayChart>
    </div>
  );
};

export default BubbleChart;
